#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.11.0  -  Calls, one share screen, fixes
#   * FIX: the media addresses (uploads / files) that v1.10.0 reset are restored from your
#     git history automatically. No more "media service address is not set".
#   * Voice and video calls from the chat (phone and camera buttons in the top bar).
#     Calls ring while the app is open. Needs a free Agora App ID (asked below).
#   * Share: "send to people" and "Share link" are on the same screen.
#   * Clips: the volume percentage now shows near the top of the screen.
#   * Me: the separate moment button is gone; the "+" on your picture works again.
#   * Firestore rules: calls, post views. Publish them after this update.
# Run from the project root:   bash update_v1110_calls_share_fixes.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="fc39e3f5eea189ee872f18661ec6b5242e42423d4d16c60e593672891997a799"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/widgets/recipient_sheet.dart ] || { echo "ERROR: v1.10.0 is not installed. Run update_v1100_chat_stories_search.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Adding the calling packages and sounds to pubspec.yaml..."
python3 - pubspec.yaml <<'PYX'
import re, sys
p = sys.argv[1]
s = open(p, encoding="utf-8").read()
changed = []
deps = [("agora_rtc_engine", "^6.6.4"), ("permission_handler", "^12.0.1"), ("wakelock_plus", "^1.2.8")]
m = re.search(r"^dependencies:[ \t]*\r?\n", s, re.M)
if not m:
    sys.exit("ERROR: no dependencies: section in pubspec.yaml")
add = ""
for name, ver in deps:
    if re.search(r"^[ \t]+" + re.escape(name) + r":", s, re.M) is None:
        add += "  %s: %s\n" % (name, ver)
        changed.append(name)
if add:
    s = s[:m.end()] + add + s[m.end():]
if "assets/sounds/" not in s:
    lines = s.split("\n")
    done = False
    for i, ln in enumerate(lines):
        if re.match(r"^  assets:\s*$", ln):
            lines.insert(i + 1, "    - assets/sounds/")
            done = True
            break
    if not done:
        for i, ln in enumerate(lines):
            if re.match(r"^  uses-material-design:", ln):
                lines[i + 1:i + 1] = ["", "  assets:", "    - assets/sounds/"]
                done = True
                break
    if not done:
        for i, ln in enumerate(lines):
            if re.match(r"^flutter:\s*$", ln):
                lines[i + 1:i + 1] = ["  assets:", "    - assets/sounds/"]
                done = True
                break
    if not done:
        sys.exit("ERROR: could not find the flutter: section in pubspec.yaml")
    s = "\n".join(lines)
    changed.append("assets/sounds/")
if changed:
    open(p, "w", encoding="utf-8").write(s)
    print("    pubspec.yaml: added " + ", ".join(changed))
else:
    print("    pubspec.yaml: already up to date")
PYX

echo "==> Android: camera and microphone permissions for calls..."
python3 - <<'PYX'
import re
m = "android/app/src/main/AndroidManifest.xml"
try:
    t = open(m).read()
    perms = ["android.permission.CAMERA", "android.permission.RECORD_AUDIO",
             "android.permission.MODIFY_AUDIO_SETTINGS", "android.permission.ACCESS_NETWORK_STATE",
             "android.permission.BLUETOOTH_CONNECT", "android.permission.INTERNET"]
    add = "".join('\n    <uses-permission android:name="%s"/>' % p for p in perms if p not in t)
    if add:
        t = re.sub(r"(<manifest[^>]*>)", lambda mo: mo.group(1) + add, t, count=1)
        open(m, "w").write(t)
        print("    AndroidManifest.xml: permissions added")
    else:
        print("    AndroidManifest.xml: permissions already there")
except FileNotFoundError:
    print("    WARNING: AndroidManifest.xml not found. Add CAMERA, RECORD_AUDIO, MODIFY_AUDIO_SETTINGS and BLUETOOTH_CONNECT by hand.")
PYX

echo "==> Media addresses (uploads and files)..."
CFG="lib/core/config.dart"
if [ -f "$CFG" ] && grep -q "CHANGE-ME" "$CFG"; then
  echo "    The addresses were reset by v1.10.0. Looking for your saved ones in git history..."
  API=""; PUB=""
  for c in $(git log --format=%H -- "$CFG" 2>/dev/null || true); do
    T="$(git show "$c:$CFG" 2>/dev/null || true)"
    [ -n "$T" ] || continue
    if printf '%s' "$T" | grep -q "CHANGE-ME"; then continue; fi
    A="$(printf '%s\n' "$T" | sed -n "s/^const String kMediaApiUrl = '\(.*\)';.*/\1/p" | head -1)"
    B="$(printf '%s\n' "$T" | sed -n "s/^const String kMediaPublicUrl = '\(.*\)';.*/\1/p" | head -1)"
    if [ -n "$A" ] && [ -n "$B" ]; then API="$A"; PUB="$B"; break; fi
  done
  if [ -n "$API" ] && [ -n "$PUB" ]; then
    echo "    Found them in an earlier commit. Restoring."
    bash tools/set_media_url.sh "$API" "$PUB"
  else
    echo "    Not found in git history. Type them again (the same two addresses as before):"
    if ( : < /dev/tty ) 2>/dev/null; then
      bash tools/set_media_url.sh < /dev/tty
    else
      echo "    Run:  bash tools/set_media_url.sh"
    fi
  fi
elif [ -f "$CFG" ]; then
  echo "    Your media addresses are in place (this update does not touch them)."
fi

echo "==> Agora App ID (for voice and video calls)..."
KEY_FILE="lib/core/agora_key.dart"
CURRENT=""
if [ -f "$KEY_FILE" ]; then
  CURRENT=$(sed -n "s/^const String kAgoraAppId = '\(.*\)';.*/\1/p" "$KEY_FILE" | head -1)
fi
NEWKEY="${AGORA_APP_ID:-}"
if [ -z "$NEWKEY" ] && [ -z "$CURRENT" ]; then
  echo "    Free App ID:  console.agora.io -> Sign up -> Projects -> Create"
  echo "    Pick  'Testing mode: APP ID'  (no token needed). 10,000 free minutes a month."
  echo "    Paste the App ID here and press Enter (or just press Enter to do it later)."
  if ( : < /dev/tty ) 2>/dev/null; then read -r -p "    Agora App ID: " NEWKEY < /dev/tty || NEWKEY=""; fi
fi
if [ -n "$NEWKEY" ]; then
  bash tools/set_agora_id.sh "$NEWKEY"
elif [ -n "$CURRENT" ]; then
  echo "    Keeping the Agora App ID that is already saved."
else
  mkdir -p lib/core
  cat > "$KEY_FILE" <<'DART'
/// Your Agora App ID for voice and video calls (console.agora.io).
/// Change it with:  bash tools/set_agora_id.sh NEW_ID   Leave it empty to turn calls off.
const String kAgoraAppId = '';
DART
  echo "    No App ID yet. Calls stay off until you run:  bash tools/set_agora_id.sh YOUR_APP_ID"
fi

echo ""
echo "Done. v1.11.0 is in place."
echo ""
echo "IMPORTANT: publish the new Firestore rules (calls and post views need them)."
echo "  Firebase console -> Build -> Firestore Database -> Rules tab"
echo "  Select everything, delete it, paste the full contents of  firebase/firestore.rules , press Publish."
echo ""
echo "Next:"
echo "  flutter clean && flutter pub get && dart analyze && flutter test"
echo '  git add -A && git commit -m "v1.11.0: calls, one share screen, fixes" && git push'
echo ""
echo "The commit also pushes your restored media addresses, so the next APK build works again."
exit 0
__PAYLOAD__

